#!/usr/bin/env bash\n\n# Nightly Disk Dragon – monitors disk usage and roars when thresholds are crossed.\n#\n# Usage: ./disk_dragon.sh [-t threshold_percent]\n#   -t <percent>   Set usage threshold (default 80).\n#   -h             Show this help message.\n\nset -euo pipefail\n\nTHRESHOLD=80\n\nwhile getopts ":t:h" opt; do\n  case $opt in\n    t) THRESHOLD=$OPTARG ;;\n    h) echo -e "Usage: $0 [-t threshold_percent]\n  -t <percent>   Set usage threshold (default 80)\n  -h             Show this help message." >&2; exit 0 ;;\n    \?) echo "Invalid option: -$OPTARG" >&2; exit 1 ;;\n  esac\ndone\n\n# Use portable output (POSIX) and skip header line\ndf -P | tail -n +2 | while read -r filesystem size used avail pcent mount; do\n  # Strip trailing % sign from the usage column\n  usage=${pcent%\%}\n  if (( usage >= THRESHOLD )); then\n    echo "🐉 Dragon warns: $mount is at ${usage}% capacity (threshold ${THRESHOLD}%)."\n  fi\n done\n
